import{_ as o,o as t,c as n,a6 as r}from"./chunks/framework.B_q3ZJNF.js";const g=JSON.parse('{"title":"关于本课程","description":"","frontmatter":{},"headers":[],"relativePath":"nginx-internals-course/about.md","filePath":"nginx-internals-course/docs/about.md"}'),a={name:"nginx-internals-course/about.md"};function s(i,e,c,p,d,l){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="关于本课程" tabindex="-1">关于本课程 <a class="header-anchor" href="#关于本课程" aria-label="Permalink to &quot;关于本课程&quot;">​</a></h1><p>这是一门给「nginx 的熟练用户」写的实现原理课。你对 nginx 的全部使用经验——写过的 <code>server</code> 块、抄过的 <code>proxy_pass</code> 和 <code>limit_req</code>、执行过的 <code>nginx -s reload</code>——在这里都会被拆开问到机制层：它凭什么又快又稳？reload 的一瞬间在线下载断没断？三台后端坏一台用户为什么看不见？</p><p>课程不读任何 C 源码。做法是用 TypeScript 亲手造一个最小的事件驱动 HTTP 服务器 <strong>tinysrv</strong>（约千行规模），让每一条原理都跑在你自己写的、可断言验证的代码上：连接注册表、HTTP/1.1 解析状态机、keep-alive、请求内存池、配置继承、反向代理、负载均衡与故障转移、漏桶限流——正文里的每段示例代码都出自这个随课程逐章长出来的实验场。</p><ul><li><strong>章节</strong>：11 章全部完成（3 个分部：并发根基、工程支柱、流量主场），另有 4 个附录（术语表、信号速查、指令对照、练习路线）。</li><li><strong>输入</strong>：主题句「nginx 实现原理」，无源仓库依赖。</li><li><strong>读者画像</strong>：配过 nginx 且大致理解配置、懂 HTTP 概念（Method/Header/Body）、写业务级 TypeScript，但没接触过 socket 层编程——socket、信号、内核缓冲这些概念在书里全部从零教。</li><li><strong>实验场</strong>：<code>companion/</code>（TypeScript + vitest），每章先写断言原理行为的测试再实现，52 个测试全绿收官，含 127.0.0.1 真实 socket 的双跳代理与故障转移集成验证。</li></ul><p>想动手跑实验场：<code>cd companion &amp;&amp; npm install &amp;&amp; npm test</code>。想从零把 tinysrv 再写一遍，见附录「练习路线」。</p>',5)])])}const m=o(a,[["render",s]]);export{g as __pageData,m as default};
